# Datalog program to determine resources accessible by user u04

# Load facts from CSV files
import "grant.csv" as grant(group, role)
import "includes.csv" as includes(role, included_role)
import "member.csv" as member(user, group)
import "permit.csv" as permit(role, resource, action)
import "revoked.csv" as revoked(user, resource)

# Find all roles for user u04 through group membership and role inclusion
user_roles(role) :- member("u04", group), grant(group, role).
user_roles(included_role) :- user_roles(role), includes(role, included_role).

# Determine which resources user u04 can access by any action
accessible_resources(resource) :- user_roles(role), permit(role, resource, action).
accessible_resources(resource) :- revoked("u04", resource), not permit(_, resource, _).

# Query the accessible resources
?- accessible_resources(resource).

# Datalog program to find users with no access to any resource

# Load facts from CSV files
import "grant.csv" as grant(group, role)
import "includes.csv" as includes(role, included_role)
import "member.csv" as member(user, group)
import "permit.csv" as permit(role, resource, action)
import "revoked.csv" as revoked(user, resource)

# Compute all roles a user has, including through inclusion
user_roles(user, role) :- grant(group, role), member(user, group).
user_roles(user, included_role) :- includes(role, included_role), user_roles(user, role).

# Compute all resources a user has access to
user_access(user, resource) :- permit(role, resource, _), user_roles(user, role).
user_access(user, resource) :- revoked(user, resource).

# Find users with no access to any resource
no_access_user(user) :- not user_access(user, _).

# Datalog program to find users who can delete but cannot read a resource

# Load facts from CSV files
import "grant.csv" as grant(group, role)
import "includes.csv" as includes(role, included_role)
import "member.csv" as member(user, group)
import "permit.csv" as permit(role, resource, action)
import "revoked.csv" as revoked(user, resource)

# Compute roles from group membership and role inclusion
role_from_group(user, role) :- member(user, group), grant(group, role).
role_from_group(user, included_role) :- member(user, group), grant(group, role), includes(role, included_role).

# Compute permissions for each user-resource pair
permission(user, resource, action) :- permit(role, resource, action), role_from_group(user, role).
permission(user, resource, action) :- revoked(user, resource), permit(role, resource, action), role_from_group(user, role).

# Find users who can delete but cannot read a resource
user_can_delete_but_not_read(user, resource) :- permission(user, resource, "delete"), not permission(user, resource, "read").

